import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

interface ModeLimitsState {
  radius: number;
  yaw: number;
  activeLimits: GeospatialLimits;
  installed: boolean;
  setOrientationWrapped: boolean;
}

const stateByCamera = new WeakMap<GeospatialCamera, ModeLimitsState>();
const TWO_PI = Math.PI * 2;
const EPS = 1e-12;

function modPeriod(value: number, period: number): number {
  const r = value % period;
  return r < 0 ? r + period : r;
}

function clampRadius(limits: GeospatialLimits, value: number): number {
  let min = limits.radiusMin;
  let max = limits.radiusMax;
  if (!Number.isFinite(min) && !Number.isFinite(max)) return value;
  if (!Number.isFinite(min)) min = -Infinity;
  if (!Number.isFinite(max)) max = Infinity;
  if (min > max) { const t = min; min = max; max = t; }
  if (!Number.isFinite(value)) {
    return Number.isFinite(min) ? min : (Number.isFinite(max) ? max : value);
  }
  return Math.min(Math.max(value, min), max);
}

function clampYaw(limits: GeospatialLimits, value: number): number {
  const min = limits.yawMin;
  const max = limits.yawMax;
  if (!Number.isFinite(min) && !Number.isFinite(max)) return value;
  if (!Number.isFinite(min)) {
    // Only an upper bound is meaningful; keep simple numeric clamp.
    return value <= max ? value : max;
  }
  if (!Number.isFinite(max)) {
    return value >= min ? value : min;
  }
  if (!Number.isFinite(value)) return min;
  const rawSpan = max - min;
  if (rawSpan >= TWO_PI - EPS) return value;
  const span = modPeriod(rawSpan, TWO_PI);
  if (span < EPS) {
    if (Math.abs(rawSpan) >= TWO_PI - EPS) return value;
    return min;
  }
  if (span >= TWO_PI - EPS) return value;

  const end = max >= min ? max : max + TWO_PI;
  const normalized = modPeriod(value - min, TWO_PI) + min;

  if (normalized <= end) {
    return normalized;
  }

  const distanceToEnd = normalized - end;
  const distanceToMin = min + TWO_PI - normalized;
  return distanceToEnd <= distanceToMin ? max : min;
}
```
