  const min = limits.yawMin;
  const max = limits.yawMax;
  if (!Number.isFinite(min) && !Number.isFinite(max)) return value;
  if (!Number.isFinite(min)) return value <= max ? value : max;
  if (!Number.isFinite(max)) return value >= min ? value : min;
  if (!Number.isFinite(value)) return min;

  const rawSpan = max - min;
  if (rawSpan >= TWO_PI - EPS) return value;
  const span = modPeriod(rawSpan, TWO_PI);
  if (span < EPS) {
    if (Math.abs(rawSpan) >= TWO_PI - EPS) return value;
    return min;
  }
  if (span >= TWO_PI - EPS) return value;

  let end = max;
  if (end < min - EPS) {
    const cycles = Math.ceil((min - end) / TWO_PI);
    end += cycles * TWO_PI;
  } else if (end >= min + TWO_PI - EPS) {
    const cycles = Math.floor((end - min) / TWO_PI);
    end -= cycles * TWO_PI;
  }

  const normalized = modPeriod(value - min, TWO_PI) + min;
